// src/plugins/vuetify.js
import "vuetify/styles";
import "@mdi/font/css/materialdesignicons.css";

import { createVuetify } from "vuetify";
import * as components from "vuetify/components";
import * as directives from "vuetify/directives";
import { THEME } from "@/config/theme";

// Theme colours and component defaults come from the shared design tokens so that
// Vuetify components look the same as the widget's own buttons, chips and cards.
const vuetify = createVuetify({
  components,
  directives,

  icons: {
    defaultSet: "mdi",
  },

  theme: {
    defaultTheme: "dashboardTheme",
    themes: {
      dashboardTheme: {
        dark: false,
        colors: {
          primary: THEME.primary,
          secondary: THEME.secondary,
          background: THEME.background,
          surface: THEME.surface,
          success: THEME.success,
          warning: THEME.warning,
          error: THEME.error,
          info: THEME.info,
          accent: THEME.accent,
        },
      },
    },
  },

  defaults: {
    VCard: { elevation: 0, rounded: "lg", border: true },
    VBtn: { rounded: "lg", height: 36, elevation: 0, class: "text-none" },
    VTextField: { variant: "outlined", density: "comfortable", color: "primary" },
    VTextarea: { variant: "outlined", density: "comfortable", color: "primary" },
    VSelect: { variant: "outlined", density: "comfortable", color: "primary" },
    VAutocomplete: { variant: "outlined", density: "comfortable", color: "primary" },
    VCombobox: { variant: "outlined", density: "comfortable", color: "primary" },
    VCheckbox: { color: "primary", density: "comfortable" },
    VSwitch: { color: "primary", inset: true, density: "comfortable" },
    VTooltip: { location: "bottom" },
  },
});

export default vuetify;
