<template>
    <div class="cf-wrap">
        <div class="cf-panel">
            <div class="cf-head">
                <div class="cf-icon"><v-icon icon="mdi-form-select" size="22" /></div>
                <div>
                    <h2 class="cf-title">Custom Query</h2>
                    <div class="cf-sub">Set your criteria and we'll build the dashboard from them</div>
                </div>
            </div>

            <div class="cf-body">
                <section v-for="(list, name) in sections" :key="name" class="cf-section">
                    <div class="cf-section-title">{{ name }}</div>
                    <div class="cf-grid">
                        <template v-for="f in list" :key="f.key">
                            <v-select v-if="f.key === 'type'" v-model="form.type" :items="f.items" variant="outlined"
                                density="comfortable" hide-details>
                                <template #label>{{ f.label }} <span class="cf-req">*</span></template>
                            </v-select>
                            <v-text-field v-else-if="f.date" v-model="form[f.key]" type="date" :label="f.label"
                                variant="outlined" density="comfortable" hide-details="auto"
                                :error-messages="errors[f.key] || ''" />
                            <v-combobox v-else v-model="form[f.key]" :items="f.items || []" :label="f.label"
                                hide-no-data clearable variant="outlined" density="comfortable" hide-details="auto"
                                :error-messages="errors[f.key] || ''" />
                        </template>
                    </div>
                </section>
            </div>

            <div class="cf-actions">
                <button type="button" class="btn-outline cf-home" @click="$emit('go-home')">
                    <v-icon icon="mdi-home-outline" size="16" /> Home
                </button>
                <button type="button" class="btn-outline" @click="reset">Clear all</button>
                <button type="button" class="btn-primary" :disabled="!form.type || hasErrors" @click="submit">Show Dashboard</button>
            </div>
        </div>
    </div>
</template>

<script>
import { useDashboardStore } from "@/store/dashboardStore";

const STATUS = ["IN_WORK", "RELEASED", "OBSOLETE", "FROZEN"];
const KEYS = ["type", "keyword", "status", "policy", "owner", "lastModifiedBy", "originator", "project", "createdFrom", "createdTo", "modifiedFrom", "modifiedTo"];
const EMPTY = () => Object.fromEntries(KEYS.map((k) => [k, ""]));

export default {
    name: "CustomFormView",
    emits: ["open-dashboard", "go-home"],
    setup() {
        return { store: useDashboardStore() };
    },
    data() {
        return { form: { ...EMPTY(), type: this.store.type } };
    },
    computed: {
        fields() {
            return [
                { key: "type", label: "Object type", section: "General", items: this.store.getTypeOptions.map((t) => t.name) },
                { key: "keyword", label: "Keyword", section: "General" },
                { key: "status", label: "Maturity state", section: "Attributes", items: STATUS },
                { key: "policy", label: "Policy", section: "Attributes", items: ["Document Release", "VPLM_SMB_Definition"] },
                { key: "owner", label: "Owner", section: "People" },
                { key: "lastModifiedBy", label: "Last modified by", section: "People" },
                { key: "originator", label: "Originator", section: "People" },
                { key: "project", label: "Collaborative space", section: "People" },
                { key: "createdFrom", label: "Created from", section: "Dates", date: true },
                { key: "createdTo", label: "Created to", section: "Dates", date: true },
                { key: "modifiedFrom", label: "Modified from", section: "Dates", date: true },
                { key: "modifiedTo", label: "Modified to", section: "Dates", date: true },
            ];
        },
        // FR-04 input validation
        errors() {
            const e = {};
            const f = this.form;
            if (f.createdFrom && f.createdTo && f.createdFrom > f.createdTo) e.createdTo = "Must be on or after Created from.";
            if (f.modifiedFrom && f.modifiedTo && f.modifiedFrom > f.modifiedTo) e.modifiedTo = "Must be on or after Modified from.";
            if ((f.keyword || "").length > 200) e.keyword = "Use at most 200 characters.";
            return e;
        },
        hasErrors() {
            return Object.keys(this.errors).length > 0;
        },
        sections() {
            const out = {};
            this.fields.forEach((f) => (out[f.section] ||= []).push(f));
            return out;
        },
    },
    methods: {
        reset() {
            this.form = EMPTY();
        },
        submit() {
            if (!this.form.type || this.hasErrors) return;
            const { type, ...values } = this.form;
            Object.keys(values).forEach((k) => (values[k] = values[k] || ""));
            this.store.setType(type); // also clears old form
            this.store.setCustomForm(values);
            this.$emit("open-dashboard", {});
        },
    },
};
</script>

<style scoped>
.cf-wrap {
    display: flex;
    justify-content: center;
    padding: 24px 16px;
}

.cf-panel {
    width: 100%;
    max-width: 760px;
    max-height: calc(100vh - 48px);
    display: flex;
    flex-direction: column;
    background: var(--dw-surface);
    border: 1px solid var(--dw-border);
    border-radius: var(--dw-radius-lg);
    overflow: hidden;
}

.cf-head {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 20px 28px;
    border-bottom: 1px solid var(--dw-border);
}

.cf-icon {
    width: 42px;
    height: 42px;
    border-radius: var(--dw-radius-lg);
    background: var(--dw-primary-soft);
    color: var(--dw-primary);
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
}

.cf-title {
    font-size: var(--dw-fs-lg);
    font-weight: var(--dw-fw-bold);
    margin: 0 0 2px;
    color: var(--dw-text);
}

.cf-sub {
    font-size: var(--dw-fs-base);
    color: var(--dw-text-muted);
}

.cf-body {
    flex: 1;
    overflow-y: auto;
    padding: 8px 28px 4px;
}

.cf-section {
    padding: 16px 0;
    border-bottom: 1px solid var(--dw-divider);
}

.cf-section:last-child {
    border-bottom: 0;
}

.cf-section-title {
    font-size: var(--dw-fs-xs);
    font-weight: var(--dw-fw-semibold);
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--dw-text-subtle);
    margin-bottom: 12px;
}

.cf-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
}

.cf-actions {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    padding: 14px 28px;
    border-top: 1px solid var(--dw-border);
    background: var(--dw-surface-alt);
}

.cf-actions button {
    height: 38px;
    padding: 0 20px;
    border-radius: var(--dw-radius);
    font-size: var(--dw-fs-md);
    font-weight: var(--dw-fw-semibold);
    cursor: pointer;
    transition: background 0.15s, box-shadow 0.15s, transform 0.1s;
}






.cf-actions button:active:not(:disabled) {
    transform: scale(0.97);
}

@media (max-width: 600px) {
    .cf-grid {
        grid-template-columns: 1fr;
    }

    .cf-head,
    .cf-body,
    .cf-actions {
        padding-left: 16px;
        padding-right: 16px;
    }
}

.cf-home {
    margin-right: auto;
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

.cf-req {
    color: var(--dw-error);
    font-weight: var(--dw-fw-bold);
}
</style>
