import { useDashboardStore } from "@/store/dashboardStore.js";
import { PLATFORM } from "@/config/platformConfig";
import { ApiError, ERROR_CODES, codeForStatus } from "./apiError";
import { ERROR_TEXT } from "@/utils/uiText";

const WRITE_METHODS = new Set(["POST", "PUT", "PATCH", "DELETE"]);

class HttpClient {
  defaultOptions = {
    credentials: "include",
    headers: {
      "Content-Type": "application/json",
    },
  };

  csrfToken = null;

  getBaseUrl() {
    const baseUrl = useDashboardStore().getBaseUrl;
    if (!baseUrl) {
      throw new ApiError(ERROR_CODES.NOT_CONFIGURED, { message: "The 3DEXPERIENCE platform URL is not available." });
    }
    return baseUrl;
  }

  getSpace3DURL() {
    const Space3DURL = useDashboardStore().getSpace3DURL;
    if (!Space3DURL) {
      throw new ApiError(ERROR_CODES.NOT_CONFIGURED, { message: "The 3DSpace URL is not available." });
    }
    return Space3DURL;
  }

  // Search calls go to the federated search service; everything else to 3DSpace.
  resolveUrl(endpoint) {
    if (endpoint.startsWith("http://") || endpoint.startsWith("https://")) return endpoint;
    const store = useDashboardStore();
    const path = endpoint.split("?")[0].toLowerCase();
    if (path.endsWith("/federated/search")) {
      return store.getServer === "OnPremise"
        ? this.getBaseUrl() + endpoint
        : this.getBaseUrl().replace("-space.", "-fedsearch.") + endpoint + "?xrequestedwith=xmlhttprequest";
    }
    return this.getSpace3DURL() + endpoint;
  }

  // 3DSpace requires a CSRF token on write calls (search calls do not).
  needsCsrf(method, url) {
    if (!WRITE_METHODS.has(method)) return false;
    try {
      return url.startsWith(this.getSpace3DURL()) && !url.includes(PLATFORM.federatedSearch);
    } catch (e) {
      return false;
    }
  }

  async fetchCsrfToken(force = false) {
    if (this.csrfToken && !force) return this.csrfToken;
    const json = await this.send("GET", this.getSpace3DURL() + PLATFORM.csrf.url, undefined, {});
    // The token is returned in a "value" node (shape: { csrf: { name, value } }).
    const token = json?.csrf?.value || json?.value || json?.data?.csrf?.value;
    if (!token) throw new ApiError(ERROR_CODES.SERVER, { message: ERROR_TEXT.securityToken });
    this.csrfToken = token;
    return token;
  }

  /**
   * options:
   *   headers        extra headers
   *   rawBody        send as-is (FormData, Blob, string) instead of JSON
   *   responseType   "json" (default) | "text"
   *   credentials    fetch credentials mode (default "include")
   */
  async request(method, endpoint, body, options = {}) {
    const url = this.resolveUrl(endpoint);
    const withCsrf = this.needsCsrf(method, url);
    const attempt = async (forceToken) => {
      const headers = { ...(options.headers || {}) };
      if (withCsrf) headers[PLATFORM.csrf.header] = await this.fetchCsrfToken(forceToken);
      return this.send(method, url, body, { ...options, headers });
    };
    try {
      return await attempt(false);
    } catch (e) {
      // An expired CSRF token is rejected with 403: refresh it once and retry.
      if (withCsrf && e instanceof ApiError && e.status === 403 && /csrf/i.test(e.detail || "")) {
        return attempt(true);
      }
      throw e;
    }
  }

  async send(method, url, body, options = {}) {
    const { headers = {}, rawBody, responseType = "json", credentials, ...fetchOptions } = options;
    const isRaw = rawBody !== undefined;
    const baseHeaders = isRaw ? {} : this.defaultOptions.headers;
    let response;
    try {
      response = await fetch(url, {
        credentials: credentials || this.defaultOptions.credentials,
        ...fetchOptions,
        method,
        headers: { ...baseHeaders, ...headers },
        ...(isRaw ? { body: rawBody } : body !== undefined ? { body: JSON.stringify(body) } : {}),
      });
    } catch (e) {
      throw new ApiError(ERROR_CODES.NETWORK, { detail: String(e?.message || e) });
    }

    if (!response.ok) {
      const detail = await response.text().catch(() => "");
      // Diagnostic log without headers, tokens or payloads.
      console.warn(`[http] ${method} ${url.split("?")[0]} -> ${response.status}`);
      throw new ApiError(codeForStatus(response.status), { status: response.status, detail });
    }

    if (response.status === 204) return null;
    if (responseType === "text") return response.text();
    const text = await response.text();
    if (!text) return null;
    try {
      return JSON.parse(text);
    } catch (e) {
      throw new ApiError(ERROR_CODES.SERVER, { status: response.status, message: "The server returned an unexpected response." });
    }
  }

  get(url, options) {
    return this.request("GET", url, undefined, options);
  }

  post(url, body, options) {
    return this.request("POST", url, body, options);
  }

  put(url, body, options) {
    return this.request("PUT", url, body, options);
  }

  patch(url, body, options) {
    return this.request("PATCH", url, body, options);
  }

  delete(url, options) {
    return this.request("DELETE", url, undefined, options);
  }
}

export default new HttpClient();
