import { initWidget, x3DDashboardUtils } from "./config/widgetConfig";
import { createApp } from "vue";
import pinia from "./store";
import initApp from "./utils/initApp";
import { useDashboardStore } from "@/store/dashboardStore";

import App from "./App.vue";
import vuetify from "./plugins/vuetify";
import { applyChartDefaults } from "./config/chartDefaults";
import { SHARING } from "./config/platformConfig";
import { registerSharingAdapter } from "./services/sharingApi";
import pnoSharingAdapter from "./services/pnoSharingAdapter";
import { logError } from "./utils/logger";
import { ERROR_TEXT } from "./utils/uiText";

applyChartDefaults();

// In-widget sharing through the platform ownership services (Share command).
if (SHARING.enabled) registerSharingAdapter(pnoSharingAdapter);

function createVueApp(widget) {
  const app = createApp(App, { widget });
  app.use(pinia);
  app.use(vuetify);
  return app;
}

if (process.env.VUE_APP_BUILD_TARGET === "widget") {
  initWidget(async (widget) => {
    const app = createVueApp(widget);
    const store = useDashboardStore(pinia);
    try {
      await initApp.get3DSpaceURL();
      await initApp.getUserDetails();
      await initApp.userCtxCollabspaces(widget);
      await store.fetchTypeConfig();
    } catch (e) {
      // Mount anyway so the user sees a clear, recoverable error instead of a blank widget.
      logError("init", "Widget start-up failed:", e);
      store.setValue("startupError", e?.message || ERROR_TEXT.widgetStart);
    }
    app.mount("#app");
    x3DDashboardUtils.disableCSS();
    widget.addEvent("onLoad", () => app);
  }, (e) => logError("init", "The widget object was not provided by 3DDashboard:", e));
} else {
  const app = createVueApp();
  useDashboardStore(pinia).fetchTypeConfig();
  app.mount("#app");
}
