// Global ApexCharts defaults so every chart in the widget shares the same font,
// axis colours, grid and mark style (thin marks, rounded bar ends, 2px lines).
import { THEME } from "@/config/theme";
import { PALETTE } from "@/utils/dashboardData";

export function applyChartDefaults() {
  window.Apex = {
    chart: {
      fontFamily: THEME.fontFamily,
      foreColor: THEME.textMuted,
      toolbar: { show: false },
      animations: { enabled: true, speed: 300 },
    },
    colors: PALETTE,
    grid: { borderColor: THEME.border, strokeDashArray: 4 },
    stroke: { width: 0, curve: "smooth" }, // line/area charts set their own 2px width
    markers: { size: 4, strokeWidth: 2, strokeColors: THEME.surface, hover: { size: 6 } },
    plotOptions: {
      bar: { borderRadius: 4, borderRadiusApplication: "end" },
      pie: { donut: { size: "64%" } },
    },
    states: { hover: { filter: { type: "darken", value: 0.9 } } },
    dataLabels: { style: { fontWeight: 600 } },
    legend: { fontSize: "12px", labels: { colors: THEME.text } },
    tooltip: { theme: "light", style: { fontFamily: THEME.fontFamily, fontSize: "12px" } },
    xaxis: { axisBorder: { color: THEME.border }, axisTicks: { color: THEME.border } },
  };
}
