import { EXTERNAL } from "@/config/platformConfig";

// Optional external project source (FR-22). Its base URL is deployment-specific
// (VUE_APP_EXT_BASE); without it the external source is reported as unavailable.
// Credentials stay in memory / widget preferences and are never stored in dashboards.
const BASE = EXTERNAL.externalApiBase;

let token = null;
let expiresAt = 0;
const pref = (name) => (window.widget?.getValue?.(name) || "").trim();
async function raw(path, options = {}) {
  if (!BASE) throw new Error("The external source isn't configured for this widget.");
  let res;
  try {
    res = await fetch(`${BASE}${path}`, {
      ...options,
      headers: {
        Accept: "application/json",
        "Content-Type": "application/json",
        ...(token && { Authorization: `Bearer ${token}` }),
      },
    });
  } catch {
    // browser blocked it (CORS / network)
    throw new Error("Cannot reach the external server (blocked by CORS or network).");
  }
  if (!res.ok) throw new Error(`External API error ${res.status}`);
  return res.json();
}

async function login() {
  const email = pref("extEmail");
  const password = pref("extPassword");
  if (!email || !password)
    throw new Error("Set External email and password in the widget preferences.");
  const json = await raw("/auth/login", {
    method: "POST",
    body: JSON.stringify({ email, password }),
  });
  token = json.data.accessToken;
  expiresAt = Date.now() + (json.data.expiresIn - 60) * 1000;
}

async function call(path) {
  if (!token || Date.now() >= expiresAt) await login();
  try {
    return await raw(path);
  } catch (e) {
    if (!String(e.message).endsWith("401")) throw e;
    token = null; // token rejected -> sign in again once
    await login();
    return raw(path);
  }
}

export default {
  isConfigured: () => !!BASE,

  ensureLogin: async () => {
    if (!token || Date.now() >= expiresAt) await login();
  },

  async getProjects() {
    const json = await call("/projects");
    return json.data?.content || json.data || [];
  },

  // tasks and sub tasks of one project (3rd API)
  async getIssues(projectKey, page = 0, size = 500) {
    const json = await call(
      `/projects/${encodeURIComponent(projectKey)}/issues?page=${page}&size=${size}`,
    );
    return json.data?.content || json.data || [];
  },
};
