import http from "./httpClient.js";
import initApp from "../utils/initApp.js";

const DETAIL_API_BY_TYPE = {
  Project: (id) => http.get(`/resources/v1/modeler/projects/${id}`),
  Task: (id) => http.get(`/resources/v1/modeler/tasks/${id}`),
  Document: (id) => http.get(`/resources/v1/modeler/documents/${id}`),
  Program: (id) => http.get(`/resources/v1/modeler/programs/${id}`),
   Engineering: (id) =>
    http.get(`/resources/v1/modeler/dseng/dseng:EngItem/${id}`, {
       headers: {
      SecurityContext: initApp.getCTX()
    }
    }),
  "Raw Material": (id) => http.get(`/resources/v1/modeler/dsrm/dsrm:RawMaterial/${id}/dsspec:Material`),
  Requirement: (id) => http.get(`/resources/v1/modeler/dsreq/dsreq:Requirement/${id}`),
  Risk: (id) => http.get(`/resources/v1/modeler/risks/${id}`),
  "Change Action": (id) => http.get(`/resources/v1/modeler/dslc/changeaction/${id}`),
  
  // Issue: (id) => http.get(`/resources/v1/modeler/dseng/dseng:Issue/${id}`),
};
class detailAPI {
  hasDetailApi(type) {
    return !!DETAIL_API_BY_TYPE[type];
  }
  fetchDetail(type, id) {
    return DETAIL_API_BY_TYPE[type](id);
  }
}
export default new detailAPI();
