<template>
  <DwDialog
    :model-value="modelValue"
    title="Which projects do you want to see?"
    subtitle="Choose where the project data comes from."
    icon="mdi-briefcase-outline"
    :busy="busy"
    max-width="480"
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <div class="sc-options">
      <button type="button" class="sc-option" :disabled="busy" @click="$emit('pick', '3dx')">
        <v-icon icon="mdi-cube-outline" size="26" />
        <span class="sc-option__title">3DEXPERIENCE</span>
        <span class="dw-caption">Project Spaces on this platform</span>
      </button>
      <button type="button" class="sc-option" :disabled="busy || !externalAvailable" @click="chooseExternal">
        <span v-if="busy" class="dw-spinner" aria-hidden="true" />
        <v-icon v-else icon="mdi-open-in-new" size="26" />
        <span class="sc-option__title">{{ busy ? "Connecting…" : "External" }}</span>
        <span class="dw-caption">{{ externalAvailable ? "Connected project system" : "Not configured for this widget" }}</span>
      </button>
    </div>
    <div v-if="error" class="dw-alert dw-alert--error" role="alert">
      <v-icon icon="mdi-alert-circle-outline" size="18" /><span>{{ error }}</span>
    </div>
  </DwDialog>
</template>

<script>
import DwDialog from "@/components/common/DwDialog.vue";
import externalApi from "@/services/externalApi";

export default {
  name: "SourceChoiceDialog",
  components: { DwDialog },
  props: { modelValue: Boolean },
  emits: ["update:modelValue", "pick"],
  data: () => ({ busy: false, error: "", externalAvailable: externalApi.isConfigured() }),
  watch: {
    modelValue(v) {
      if (v) this.error = "";
    },
  },
  methods: {
    async chooseExternal() {
      this.busy = true;
      this.error = "";
      try {
        await externalApi.ensureLogin(); // uses the widget preferences
        this.$emit("pick", "external");
      } catch (e) {
        this.error = e.message;
      } finally {
        this.busy = false;
      }
    },
  },
};
</script>

<style scoped>
.sc-options {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--dw-sp-3);
}
.sc-option {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: var(--dw-sp-5) var(--dw-sp-3);
  border: 1px solid var(--dw-border);
  border-radius: var(--dw-radius-lg);
  background: var(--dw-surface);
  color: var(--dw-primary);
  font-family: inherit;
  cursor: pointer;
  text-align: center;
  transition: border-color var(--dw-transition), background var(--dw-transition);
}
.sc-option:hover:not(:disabled) {
  border-color: var(--dw-primary);
  background: var(--dw-primary-soft);
}
.sc-option:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}
.sc-option__title {
  font-size: var(--dw-fs-md);
  font-weight: var(--dw-fw-semibold);
  color: var(--dw-text);
}
@media (max-width: 420px) {
  .sc-options {
    grid-template-columns: 1fr;
  }
}
</style>
