<template>
  <div class="panel">
    <div class="panel-head">
      <div class="panel-title">{{ chart.title }}</div>

      <div class="panel-actions">
        <button type="button" class="icon-btn icon-btn--sm" :aria-label="`Refresh ${chart.title}`" title="Refresh chart" @click="$emit('refresh')"><v-icon icon="mdi-refresh" /></button>
        <button type="button" class="icon-btn icon-btn--sm" :aria-label="`Move ${chart.title} up`" title="Move up" @click="$emit('move', -1)"><v-icon icon="mdi-arrow-up" /></button>
        <button type="button" class="icon-btn icon-btn--sm" :aria-label="`Move ${chart.title} down`" title="Move down" @click="$emit('move', 1)"><v-icon icon="mdi-arrow-down" /></button>
        <button type="button" class="icon-btn icon-btn--sm" :aria-label="`Remove ${chart.title}`" title="Remove chart" @click="$emit('remove')"><v-icon icon="mdi-delete-outline" /></button>
      </div>
    </div>

    <DonutChart v-if="chart.kind === 'donut'" :key="chart.id" :chart="chart" @drill="onDrill" />
    <BarChart v-else-if="chart.kind === 'bar-h'" :key="chart.id" :chart="chart" horizontal @drill="onDrill" />
    <LineAreaChart v-else-if="chart.kind === 'line' || chart.kind === 'area'" :key="chart.id" :chart="chart" @drill="onDrill" />
    <BarChart v-else :key="chart.id" :chart="chart" @drill="onDrill" />
  </div>
</template>

<script>
import DonutChart from "@/components/charts/DonutChart.vue";
import BarChart from "@/components/charts/BarChart.vue";
import LineAreaChart from "@/components/charts/LineAreaChart.vue";

export default {
  name: "ChartPanel",
  components: { DonutChart, BarChart, LineAreaChart },
  props: { chart: { type: Object, required: true } },
  emits: ["move", "remove", "drill", "refresh"],

  methods: {
    onDrill(payload) {
      this.$emit("drill", payload);
    },
  },
};
</script>

<style scoped>
.panel {
  background: var(--dw-surface);
  border: 1px solid var(--dw-border);
  border-radius: var(--dw-radius-lg);
  box-shadow: var(--dw-shadow-sm);
  padding: var(--dw-sp-3) var(--dw-sp-4) var(--dw-sp-4);
  min-width: 0;
  width: 100%;
  box-sizing: border-box;
}
.panel-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--dw-sp-2);
  margin-bottom: var(--dw-sp-2);
}
.panel-title {
  font-size: var(--dw-fs-md);
  font-weight: var(--dw-fw-semibold);
  color: var(--dw-primary);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.panel-actions {
  display: flex;
  gap: 2px;
  flex-shrink: 0;
}
</style>
